           for (List<ArrayData> list : arrays.values()) {
               if (list.size() <= 1) continue;

               ArrayData base = null;
               for (ArrayData data : list) {
                   String folderName = data.context.file.getParentFile().getName();
                   if (SdkConstants.FD_RES_VALUES.equals(folderName)) {
